    <span className="mountain-day-temperature"><small>Max / Min</small><b><em style={maxTone?{'--mountain-temp-tone':maxTone.color} as CSSProperties:undefined}>{Number.isFinite(day.temperatureMax)?`${Math.round(day.temperatureMax)}°`:'–'}</em><i aria-hidden="true"> / </i><em style={minTone?{'--mountain-temp-tone':minTone.color} as CSSProperties:undefined}>{Number.isFinite(day.temperatureMin)?`${Math.round(day.temperatureMin)}°`:'–'}</em></b></span>
